query_items = items or []
raw_records = []

for entry in query_items:
    item = entry.get("json") if isinstance(entry, dict) and isinstance(entry.get("json"), dict) else entry
    if not isinstance(item, dict):
        continue
    records = item.get("records")
    if records is None and item.get("Id"):
        records = [item]
    for record in records or []:
        if isinstance(record, dict):
            raw_records.append(record)

contacts = []
for record in raw_records:
    account = record.get("Account") or {}
    email = str(record.get("Email") or "").strip().lower()

    website = str(account.get("Website") or "").strip().lower()
    if "://" in website:
        website = website.split("://", 1)[1]
    if website.startswith("www."):
        website = website[4:]
    for sep in ("/", "?", "#", ":"):
        if sep in website:
            website = website.split(sep, 1)[0]
    domain = website.strip().strip(".")
    if " " in domain or "." not in domain:
        domain = ""

    if not email or not domain:
        continue

    first_name = str(record.get("FirstName") or "").strip()
    last_name = str(record.get("LastName") or "").strip()
    account_name = str(account.get("Name") or "").strip() or domain

    company_properties = {
        "name": account_name,
        "domain": domain,
    }
    city = str(account.get("BillingCity") or "").strip()
    country = str(account.get("BillingCountry") or "").strip()
    if city:
        company_properties["city"] = city
    if country:
        company_properties["country"] = country

    revenue = 0.0
    revenue_raw = account.get("AnnualRevenue")
    if revenue_raw:
        try:
            revenue = float(str(revenue_raw).replace(",", "").replace("$", ""))
        except Exception:
            revenue = 0.0
    if revenue > 0:
        company_properties["annualrevenue"] = str(int(revenue))

    employees = 0
    employees_raw = account.get("NumberOfEmployees")
    if employees_raw:
        try:
            employees = int(float(str(employees_raw).replace(",", "")))
        except Exception:
            employees = 0
    if employees > 0:
        company_properties["numberofemployees"] = str(int(employees))

    contact_properties = {
        "email": email,
        "company": account_name,
    }
    if first_name:
        contact_properties["firstname"] = first_name
    if last_name:
        contact_properties["lastname"] = last_name
    title = str(record.get("Title") or "").strip()
    phone = str(record.get("Phone") or "").strip()
    if title:
        contact_properties["jobtitle"] = title
    if phone:
        contact_properties["phone"] = phone

    contacts.append({
        "sf_contact_id": str(record.get("Id") or ""),
        "sf_account_id": str(record.get("AccountId") or account.get("Id") or ""),
        "contact_email": email,
        "company_domain": domain,
        "account_name": account_name,
        "company_properties": company_properties,
        "contact_properties": contact_properties,
    })

for contact in contacts:
    contact["batch_fetched"] = len(raw_records)
    contact["batch_eligible"] = len(contacts)

return [{
    "contacts": contacts,
    "fetched": len(raw_records),
    "eligible": len(contacts),
}]

rows = []
batch_fetched = 0
batch_eligible = 0

for entry in items or []:
    row = entry.get("json") if isinstance(entry, dict) and isinstance(entry.get("json"), dict) else entry
    if not isinstance(row, dict):
        continue
    if "contacts" in row and not row.get("status"):
        batch_fetched = max(batch_fetched, int(row.get("fetched") or 0))
        batch_eligible = max(batch_eligible, int(row.get("eligible") or 0))
        continue
    if "$error" in row:
        error = row.get("$error") or {}
        source = row.get("item") if isinstance(row.get("item"), dict) else {}
        rows.append({
            "status": "failed",
            "contact_email": source.get("contact_email", ""),
            "account_name": source.get("account_name", ""),
            "error": str(error.get("message") or error or "Sub-workflow failed"),
        })
    elif row.get("status"):
        rows.append(row)

synced = [row for row in rows if row.get("status") == "synced"]
failed = [row for row in rows if row.get("status") == "failed"]
fetched = max([batch_fetched] + [int(row.get("batch_fetched") or 0) for row in rows])
eligible = max([batch_eligible] + [int(row.get("batch_eligible") or 0) for row in rows])

return [{
    "status": "success" if not failed else "partial",
    "summary": {
        "fetched": fetched,
        "eligible": eligible,
        "synced": len(synced),
        "failed": len(failed),
        "companies_created": sum(1 for row in synced if row.get("company_action") == "created"),
        "companies_updated": sum(1 for row in synced if row.get("company_action") == "updated"),
        "contacts_created": sum(1 for row in synced if row.get("contact_action") == "created"),
        "contacts_updated": sum(1 for row in synced if row.get("contact_action") == "updated"),
    },
    "results": rows,
}]
